package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class DemandPlanningBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String name:new String[]{"DemandBrowserPlanner","DemandBrowserReviewer"})Service.createAccount(db,map("name",name,"role","agent","password",WorkflowSupport.PASSWORD));db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var pc=browser.newContext();var rc=browser.newContext()){
   var planner=pc.newPage();h.login(planner,"DemandBrowserPlanner");planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Portfolio planning").setExact(true)).press("Enter");planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Create a portfolio")).press("Enter");planner.getByLabel("Portfolio name",new Page.GetByLabelOptions().setExact(true)).fill("Customer service investments");planner.getByLabel("Portfolio purpose",new Page.GetByLabelOptions().setExact(true)).fill("Reduce time to resolve customer needs");planner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create record →")).press("Enter");String portfolio=planner.url().substring(planner.url().lastIndexOf('/')+1);planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Compare portfolio demands")).press("Enter");assertThat(planner.locator("main")).containsText("No assessed demands");planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Submit a demand")).press("Enter");assertThat(planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assess and decide demand"))).hasCount(0);planner.getByLabel("Demand summary",new Page.GetByLabelOptions().setExact(true)).fill("Faster customer onboarding <script>");planner.getByLabel("Business case",new Page.GetByLabelOptions().setExact(true)).fill("Reduce manual coordination across service teams");planner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create record →")).press("Enter");String id=planner.url().substring(planner.url().lastIndexOf('/')+1);RiskAssessmentsBrowserAcceptance.change(planner,"screen");planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assess and decide demand")).press("Enter");planner.getByLabel("Portfolio",new Page.GetByLabelOptions().setExact(true)).selectOption(portfolio);planner.getByLabel("Planning year",new Page.GetByLabelOptions().setExact(true)).fill("2027");planner.getByLabel("Business value",new Page.GetByLabelOptions().setExact(true)).fill("5");planner.getByLabel("Strategic alignment",new Page.GetByLabelOptions().setExact(true)).fill("4");planner.getByLabel("Urgency",new Page.GetByLabelOptions().setExact(true)).fill("3");planner.getByLabel("Delivery effort",new Page.GetByLabelOptions().setExact(true)).fill("2");planner.getByLabel("Assessment rationale").fill("High customer value with a bounded delivery effort <script>");planner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save demand assessment")).press("Enter");assertThat(planner.locator("main")).containsText("Score 84 / 100");planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Compare portfolio demands").setExact(true)).press("Enter");assertThat(planner.locator("main")).containsText("2027 planning · 1 visible assessed demands");assertThat(planner.locator("main h3")).containsText("#1");ReleaseBrowserAcceptance.accessible(planner);planner.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/demand-priorities-light.png")).setFullPage(true));planner.locator("main a[href='/record/demand/"+id+"/planning']").press("Enter");planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Demand workspace").setExact(true)).press("Enter");RiskAssessmentsBrowserAcceptance.change(planner,"qualified");planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assess and decide demand")).press("Enter");planner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Request or review demand approval")).press("Enter");planner.getByLabel("Reviewer username").fill("DemandBrowserReviewer");planner.locator("select[name=target_state]").selectOption("approved");planner.getByLabel("Reason for review").fill("Review the assessed investment before approval");planner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Request review").setExact(true)).press("Enter");
   var reviewer=rc.newPage();h.login(reviewer,"DemandBrowserReviewer");reviewer.navigate(h.base()+"/record/demand/"+id+"/planning");assertThat(reviewer.locator("main")).containsText("High customer value");reviewer.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Request or review demand approval")).press("Enter");reviewer.getByLabel("Decision",new Page.GetByLabelOptions().setExact(true)).selectOption("approved");reviewer.getByLabel("Review comment").fill("Business value, alignment and effort checked");reviewer.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record decision")).press("Enter");planner.navigate(h.base()+"/record/demand/"+id+"/planning");planner.getByLabel("Investment decision",new Page.GetByLabelOptions().setExact(true)).selectOption("approved");planner.getByLabel("Decision rationale").fill("Approve the reviewed investment for delivery planning");planner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record demand decision")).press("Enter");assertThat(planner.locator("main")).containsText("Stage: approved");assertThat(planner.locator("main")).containsText("Decision: approved");assertThat(planner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record demand decision"))).hasCount(0);planner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");planner.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(planner);assertEquals(false,planner.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(planner.locator("main script")).hasCount(0);planner.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/demand-decision-dark.png")).setFullPage(true));
  }
 }
}
